#include <iostream>
#include <memory>
#include <vector>

class NonVirtualClass {
    int data{42};
public:
    void display() const { std::cout << "NonVirtual\n"; }
};

class VirtualClass {
    int data{42};
public:
    virtual void display() const { std::cout << "VirtualClass\n"; }
    virtual ~VirtualClass() = default;
};

int main() {
    std::cout << "Size of NonVirtualClass: " << sizeof(NonVirtualClass) << " bytes\n";
    std::cout << "Size of VirtualClass (includes vptr): " << sizeof(VirtualClass) << " bytes\n";

    std::unique_ptr<VirtualClass> obj = std::make_unique<VirtualClass>();
    obj->display();
    return 0;
}

#include <iostream>
#include <iomanip>
#include <vector>
#include <string>
#include <typeinfo>

class Employee {
private:
    std::string name;
public:
    explicit Employee(std::string n) : name(std::move(n)) {}
    virtual ~Employee() = default;
    virtual void print() const {
        std::cout << "Employee: " << name << "\n";
    }
    virtual double earnings() const = 0;
    const std::string& getName() const { return name; }
};

class CommissionEmployee : public Employee {
private:
    double grossSales;
    double commissionRate;
public:
    CommissionEmployee(std::string n, double sales, double rate)
        : Employee(std::move(n)), grossSales(sales), commissionRate(rate) {}

    void print() const override {
        Employee::print();
        std::cout << "  Gross Sales: " << grossSales << ", Rate: " << commissionRate << "\n";
    }
    double earnings() const override { return grossSales * commissionRate; }
};

class BasePlusCommissionEmployee : public CommissionEmployee {
private:
    double baseSalary;
public:
    BasePlusCommissionEmployee(std::string n, double sales, double rate, double salary)
        : CommissionEmployee(std::move(n), sales, rate), baseSalary(salary) {}

    void print() const override {
        CommissionEmployee::print();
        std::cout << "  Base Salary: " << baseSalary << "\n";
    }
    double earnings() const override { return CommissionEmployee::earnings() + baseSalary; }
    double getBaseSalary() const { return baseSalary; }
    void setBaseSalary(double s) { baseSalary = s; }
};

int main() {
    std::cout << std::fixed << std::setprecision(2);

    std::vector<Employee*> employees;
    employees.push_back(new CommissionEmployee("Sue Jones", 10000.0, 0.06));
    employees.push_back(new BasePlusCommissionEmployee("Bob Lewis", 5000.0, 0.04, 300.0));

    for (Employee* empPtr : employees) {
        empPtr->print();
        auto* basePlusPtr = dynamic_cast<BasePlusCommissionEmployee*>(empPtr);
        if (basePlusPtr != nullptr) {
            std::cout << "  [Downcast Success] Old Base: $" << basePlusPtr->getBaseSalary() << "\n";
            basePlusPtr->setBaseSalary(basePlusPtr->getBaseSalary() * 1.10);
            std::cout << "  [Downcast Success] New Base (10% inc): $" << basePlusPtr->getBaseSalary() << "\n";
        }
        std::cout << "  Total Earnings: $" << empPtr->earnings() << "\n\n";
    }

    for (const Employee* empPtr : employees) {
        std::cout << "Deleting dynamic object of type: " << typeid(*empPtr).name() << "\n";
        delete empPtr;
    }
    return 0;
}
